from chapter09_common import *
B=Block('c')
NUMERIC=[]
def verify(name,a,b):
 assert math.isclose(a,b,rel_tol=1e-8,abs_tol=1e-8),(name,a,b)
 NUMERIC.append(name)
def angle(p,a,o,b):
 u=subv(p[a],p[o]);v=subv(p[b],p[o]);return math.degrees(math.acos(max(-1,min(1,sum(u[i]*v[i] for i in (0,1))/(dist(p[a],p[o])*dist(p[b],p[o]))))))
def cp(angles,r=5):return dict(O=[0,0],**{k:polar([0,0],v,r) for k,v in angles.items()})
def cv(ps='ABCD',segments=None,through='A',**kw):return sc(ps,poly() if segments is None else segments,circles=[circle('O',through)],**kw)
def oc(ps,center='O'):return equal(*[(center,n) for n in ps])
def put(n,part,condition,answer,steps,p,v,views=None,**kw):
 printed=kw.pop('printed',[209] if n==795 else [210] if n<=801 else [210,211] if n==802 else [211] if n<=806 else [211,212] if n==807 else [212] if n<=811 else [213])
 B.add(n,part,condition,answer,steps,p,v,views,printed=printed,**kw)
def tangent_polygon(normals,r=3):
 q={'O':[0,0]};ts=[polar([0,0],t,r) for t in normals];ns=[polar([0,0],t,1) for t in normals]
 for i in range(len(normals)):
  q[chr(65+i)]=inter(ts[i-1],addv(ts[i-1],[-ns[i-1][1],ns[i-1][0]]),ts[i],addv(ts[i],[-ns[i][1],ns[i][0]]));q['_T'+str(i)]=ts[i]
 return q
def tc(p,ns='ABCD'):
 out=[]
 for i,a in enumerate(ns):
  b=ns[(i+1)%len(ns)];t='_T'+str(i);out.extend([col(a,t,b),perp('O',t,a,b)])
 return out+[equal(*[('O','_T'+str(i)) for i in range(len(ns))])]
def circum(a,b,c):
 ab=mid(a,b);ac=mid(a,c);u=subv(b,a);v=subv(c,a)
 return inter(ab,addv(ab,[-u[1],u[0]]),ac,addv(ac,[-v[1],v[0]]))
