s=math.sqrt(3)
def doublecase(second=False):
 p=dict(O=[-s,0],Q=[s,0],A=[0,3],B=[0,-3])
 p.update(dict(C=[-2*s,-3],D=[-s,0],K=[-s,-4]) if second else dict(C=[-2*s,3],D=[2*s,3],K=[0,5]))
 p['T']=circum(p['B'],p['C'],p['D']);return p
p=doublecase();q=doublecase(True)
