put(804,'single','Докажите: если в прямоугольник можно вписать окружность, то этот прямоугольник — квадрат.','Все стороны прямоугольника равны; это квадрат.',[
 row('Используй вписанную окружность.','У описанного четырёхугольника AB+CD = BC+AD.','Равенство сумм противоположных сторон.',82),
 row('Используй свойства прямоугольника.','AB=CD и BC=AD, поэтому 2AB=2BC и AB=BC.','Противоположные стороны прямоугольника равны.',51),
 row('Назови полученную фигуру.','У прямоугольника равны соседние, а значит все четыре стороны. Такой прямоугольник называется квадратом.','Определение квадрата.',53)],p,v,[v,w,w],checks=para_checks()+[equal(('A','B'),('B','C')),perp('A','B','B','C')])
