put(807,'single' ,'Докажите: если в выпуклом четырёхугольнике суммы противоположных сторон равны, то в него можно вписать окружность.','Выпуклый ABCD с AB+CD=BC+AD имеет вписанную окружность.',[
 row('Сначала получи окружность, лежащую внутри фигуры.','Возьмём маленький круг, касающийся сторон угла A и лежащий внутри ABCD. Увеличиваем его, двигая центр по внутренней биссектрисе A. Пока круг внутри четырёхугольника, он касается AB и AD; при первом новом контакте он коснётся BC или CD. Контакт наступит, так как четырёхугольник ограничен.','Гомотетическое увеличение круга в угле; непрерывность расстояний до сторон.',[39,76]),
 row('Как расположены три точки касания?','При необходимости переобозначим вершины по кругу: круг касается AB,BC,AD и целиком лежит внутри ABCD. Поэтому точки касания принадлежат самим сторонам, а не их продолжениям. Если уже есть касание CD, доказательство закончено.','Выбор первого контакта сохраняет включение круга; выпуклость.',[46,82]),
 row('Предположи, что CD ещё не касается круга.','Из C проведём вторую касательную к кругу. Поскольку круг внутри угла BCD, эта касательная идёт внутри него и отсекает угол D; обозначим её пересечение с AD через E. Контакты с AB и AD не позволяют ей пересечь AB раньше AD. Поэтому E лежит между A и D, и ABCE — описанный четырёхугольник.','Две опорные касательные из внешней точки; расположение круга внутри выпуклой фигуры.',[22,76]),
 row('Вычти два равенства сторон.','Для ABCE: AB+CE=BC+AE. Для исходного ABCD: AB+CD=BC+AD. Вычитая первое из второго, получаем CD−CE=AD−AE=DE, то есть CD=CE+DE.','Свойство описанного четырёхугольника и условие задачи.',82),
 row('Почему это невозможно?','Если E≠D, треугольник CED невырожден и CD<CE+DE по неравенству треугольника. Полученное равенство невозможно. Значит E=D: CD и есть касательная. Круг касается всех четырёх сторон и вписан в ABCD.','Строгое неравенство треугольника; противоречие.',32)],p,v,[w,z,z,z,z],checks=tc(p),cases=[(q807,v807,'Предположение: CD не касается — равенство сторон нарушается',3,[col('A','E','D'),perp('O','F','C','E'),equal(('O','T'),('O','F'))])],notes=['Сначала строится круг внутри выпуклой фигуры. Это устраняет скрытое предположение о касании продолжений сторон в сокращённом доказательстве.'])
