put(812,'single','Докажите: около выпуклого четырёхугольника, образованного при пересечении биссектрис углов трапеции, можно описать окружность. Предполагается, что названный четырёхугольник невырожден.','Четырёхугольник пересечений биссектрис вписанный.',[
 row('Сравни углы при одной боковой стороне.','Обозначим основания AD∥BC. Углы A и B в сумме дают 180°, поэтому половины этих углов в сумме дают 90°.','Односторонние углы при параллельных прямых.',29),
 row('Как расположены биссектрисы?','Биссектрисы A и B перпендикулярны: вместе с AB они образуют треугольник с двумя углами в сумме 90°. Точно так же перпендикулярны биссектрисы C и D.','Сумма углов треугольника.',31),
 row('Примени признак вписанности.','В выпуклом четырёхугольнике пересечений биссектрис две противоположные вершины P и R имеют прямые углы. Их сумма 180°, значит четырёхугольник вписанный.','Признак вписанного четырёхугольника.',83)],p,v,[v,w,z],checks=[par('A','D','B','C'),perp('A','P','B','P'),perp('C','R','D','R'),oc('PQRS')],notes=['Не утверждается, что любые четыре биссектрисы трапеции всегда образуют невырожденный четырёхугольник.'])
