put(818,'single','Даны две параллельные прямые и точка P, не лежащая ни на одной из них. Постройте окружность, проходящую через P и касающуюся обеих прямых.','Если P внутри полосы — два решения; если вне полосы — решений нет.',[
 row('Какими обязаны быть радиус и положение центра?','Пусть расстояние между параллельными прямыми равно h. Радиус искомой окружности r=h/2, а центр лежит на средней параллели между ними. Построй эту прямую.','Центр равноудалён от двух параллельных касательных.',76),
 row('Как обеспечить прохождение через P?','Построй вспомогательную окружность с центром P радиуса r. Её пересечения со средней параллелью — возможные центры искомых окружностей.','Условие OP=r.',22),
 row('Построй оба решения внутри полосы.','Когда P внутри полосы, расстояние от P до средней параллели меньше r. Есть два центра O и Q. Каждая окружность радиуса r с таким центром проходит через P и касается обеих данных прямых. Два решения показаны раздельно.','Прямая пересекает окружность в двух точках при d<r.',76),
 row('Разбери точку вне полосы и докажи полноту.','Если P вне полосы, её расстояние до средней параллели больше r: пересечений и решений нет. Точка на одной из данных прямых исключена условием; там был бы один центр. Иных решений нет, потому что любой центр обязан удовлетворять обоим построенным условиям.','Случаи d>r и d=r; необходимое и достаточное условия центра.',76)],p,v,[w,z,f,f],checks=[par('U','V','W','X'),par('M','N','U','V'),col('M','Q','O'),equal(('P','O'),('P','Q'),('O','T'),('O','H')),perp('O','T','U','V')],cases=[(p,f2,'Второе решение внутри полосы',3,[equal(('Q','P'),('O','P'))]),(q,qv,'Точка вне полосы: пересечений нет',4,[])],labels={'U':'','V':'','W':'','X':'','M':'','N':'','J':''})
